create or replace function public.system_add_performance_log(p_metric text,p_value numeric,p_unit text default null,p_note text default null,p_recorded_at timestamptz default now()) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_user uuid:=auth.uid(); v_row public.performance_logs; begin if v_user is null then raise exception 'AUTH_REQUIRED'; end if; if length(trim(coalesce(p_metric,'')))<2 or p_value is null or p_value<0 then raise exception 'INVALID_PERFORMANCE_LOG'; end if; insert into public.performance_logs(user_id,metric,value,unit,note,source,metadata,recorded_at) values(v_user,upper(trim(p_metric)),p_value,nullif(trim(coalesce(p_unit,'')),''),nullif(trim(coalesce(p_note,'')),''),'MANUAL',jsonb_build_object('verified',false,'authoritative_record',true),coalesce(p_recorded_at,now())) returning * into v_row; return to_jsonb(v_row); end $$;
create or replace function public.system_add_wealth_log(p_type text,p_amount numeric,p_currency text default 'KES',p_note text default null,p_recorded_on date default current_date) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_user uuid:=auth.uid(); v_row public.wealth_logs; v_type text:=upper(trim(coalesce(p_type,'OTHER'))); begin if v_user is null then raise exception 'AUTH_REQUIRED'; end if; if p_amount is null or p_amount<0 then raise exception 'INVALID_AMOUNT'; end if; if v_type not in ('SAVINGS','INCOME','DEBT CLEARED','INVESTMENT','CHAMA','OTHER') then v_type:='OTHER'; end if; insert into public.wealth_logs(user_id,type,amount,currency,note,source,metadata,recorded_on) values(v_user,v_type,p_amount,upper(coalesce(nullif(trim(p_currency),''),'KES')),nullif(trim(coalesce(p_note,'')),''),'MANUAL',jsonb_build_object('authoritative_record',true),coalesce(p_recorded_on,current_date)) returning * into v_row; perform public.system_orchestrate_progression(); return to_jsonb(v_row); end $$;
create or replace function public.system_add_learning_record(p_skill_id bigint,p_title text,p_source_title text,p_source_type text,p_duration_minutes integer,p_learning_summary text,p_key_takeaways jsonb default '[]'::jsonb,p_application_plan text default null,p_mastery_evidence jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_user uuid:=auth.uid(); v_row public.learning_records; begin if v_user is null then raise exception 'AUTH_REQUIRED'; end if; if not exists(select 1 from public.skills where id=p_skill_id) then raise exception 'SKILL_NOT_FOUND'; end if; if length(trim(coalesce(p_source_title,'')))<2 or p_duration_minutes is null or p_duration_minutes<=0 then raise exception 'INVALID_LEARNING_RECORD'; end if; insert into public.learning_records(user_id,skill_id,title,source_title,source_type,duration_minutes,learning_summary,key_takeaways,application_plan,mastery_evidence) values(v_user,p_skill_id,coalesce(nullif(trim(p_title),''),trim(p_source_title)),trim(p_source_title),upper(coalesce(nullif(trim(p_source_type),''),'OTHER')),least(p_duration_minutes,1440),nullif(trim(coalesce(p_learning_summary,'')),''),coalesce(p_key_takeaways,'[]'::jsonb),nullif(trim(coalesce(p_application_plan,'')),''),coalesce(p_mastery_evidence,'{}'::jsonb)) returning * into v_row; perform public.system_orchestrate_progression(); return to_jsonb(v_row); end $$;
revoke all on function public.system_add_performance_log(text,numeric,text,text,timestamptz) from public,anon; revoke all on function public.system_add_wealth_log(text,numeric,text,text,date) from public,anon; revoke all on function public.system_add_learning_record(bigint,text,text,text,integer,text,jsonb,text,jsonb) from public,anon; grant execute on function public.system_add_performance_log(text,numeric,text,text,timestamptz) to authenticated,service_role; grant execute on function public.system_add_wealth_log(text,numeric,text,text,date) to authenticated,service_role; grant execute on function public.system_add_learning_record(bigint,text,text,text,integer,text,jsonb,text,jsonb) to authenticated,service_role;
-- Critical tables: authenticated users retain SELECT policies, mutations go through SECURITY DEFINER RPCs.
